package cn.huankan.event;
import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class PriorityRulesTest {
 PriorityRules.Input input(String level,boolean intact,String status){return new PriorityRules.Input("event","evidence",level,"真实机构",Instant.parse("2026-10-12T00:00:00Z"),Instant.parse("2026-10-12T01:00:00Z"),intact,status,List.of("货币政策"),false,false,false,false,"NEW_EVENT");}
 @Test void backfillAndRevisionNeverPretendToBeFreshNews(){var i=input("L0",true,"FIELD_MATCHED");for(String kind:Arrays.asList(null,"HISTORICAL_BACKFILL","REVISION")){var historical=new PriorityRules.Input(i.eventId(),i.evidenceId(),i.level(),i.publisher(),i.publishedAt(),i.asOf(),true,i.factStatus(),i.categories(),false,false,false,false,kind);assertEquals(60,PriorityRules.score(historical).total());assertEquals(75,PriorityRules.score(historical,PriorityRules.LEGACY_VERSION).total());}assertEquals(0,PriorityRules.score(input("L2",true,"FIELD_MATCHED")).components().get("官方发布时间新近程度"));}
 @Test void oldFrozenInputsStillReproduceUsingTheirActualVersion(){var i=input("L0",true,"FIELD_MATCHED");var legacy=new PriorityRules.Input(i.eventId(),i.evidenceId(),i.level(),i.publisher(),i.publishedAt(),i.asOf(),true,i.factStatus(),i.categories(),false,false,false,false);assertEquals(75,PriorityRules.score(legacy,PriorityRules.LEGACY_VERSION).total());assertThrows(IllegalArgumentException.class,()->PriorityRules.score(legacy,"unknown"));}
 @Test void scoresAreReproducibleAndExplainEveryPoint(){var i=input("L0",true,"FIELD_MATCHED");var a=PriorityRules.score(i);assertEquals(a,PriorityRules.score(i));assertEquals(75,a.total());assertEquals(a.total(),a.components().values().stream().mapToInt(Integer::intValue).sum());}
 @Test void aggregatedLeadDoesNotGainOfficialOrFactCredit(){var a=PriorityRules.score(input("L2",true,"FIELD_MATCHED"));assertEquals(0,a.components().get("官方来源等级"));assertEquals(0,a.components().get("证据完整且字段核对"));assertTrue(a.reasons().stream().anyMatch(x->x.contains("数量与重复提及不加分")));}
 @Test void damagedEvidenceCannotReceiveVerifiedFactCredit(){assertEquals(0,PriorityRules.score(input("L0",false,"FIELD_MATCHED")).components().get("证据完整且字段核对"));assertEquals(0,PriorityRules.score(input("L0",true,"CONFLICT")).components().get("官方来源等级"));}
 @Test void sourceConfirmationIsDifferentFromFieldVerification(){assertEquals(0,PriorityRules.score(input("L0",true,"SOURCE_CHECKED")).components().get("证据完整且字段核对"));}
 @Test void missingOrFuturePublicationReceivesNoFreshness(){var i=input("L0",true,"FIELD_MATCHED");for(Instant at:Arrays.asList(null,i.asOf().plusSeconds(1)))assertEquals(0,PriorityRules.score(new PriorityRules.Input(i.eventId(),i.evidenceId(),i.level(),i.publisher(),at,i.asOf(),i.intact(),i.factStatus(),i.categories(),false,false,false,false)).components().get("官方发布时间新近程度"));}
 @Test void classificationsCoverRequestedTopicsWithoutCreatingEvents(){assertEquals(List.of(),PriorityRules.categories("普通公告",null));assertTrue(PriorityRules.categories("Optical data center semiconductor supply chain",null).containsAll(List.of("光通信与数据中心","AI与半导体","产业链重大变化")));assertEquals(List.of("汇率"),PriorityRules.categories("官方观测","EXR.D.USD.EUR.SP00.A"));}
}
